First of all, I'm not claiming that my framework will save industrial C/C++ development. It's just a hobby project.<p>Industrial code needs safer code, not easier code. But when you're developing a blog at 8 PM, long template errors are annoying.<p>You need CRUD and RDBMS. It's simple.<p>CWIST is for that kind of work.<p>It sacrifices memory safety, smart pointers, and modern C++ abstractions. In return, compile errors are more predictable.<p><pre><code>  #include &lt;stdio.h&gt;
  #include &lt;cwist/app.h&gt;
  #include &lt;cwist/core/db/pool.h&gt;
  #include &lt;cwist/core/template/template.h&gt;

  static cwist_db_pool_t *g_db_pool;

  static void <em>send</em>_error(cwist_http_response *res, const char *<em>msg</em>) {
    res-&gt;status_code = CWIST_HTTP_INTERNAL_ERROR;
    cwist_http_header_add(&amp;res-&gt;headers, &quot;Content-Type&quot;, &quot;text/plain&quot;);
    cwist_sstring_assign(res-&gt;body, <em>msg</em>);
  }

  static void render(cwist_http_response *res, const char *path, cJSON *ctx) {
    cwist_sstring *html = cwist_template_render_file(path, ctx);
    if (html) {
      cwist_http_header_add(&amp;res-&gt;headers, &quot;Content-Type&quot;, &quot;text/html&quot;);
      cwist_sstring_assign(res-&gt;body, html-&gt;data);
      cwist_sstring_destroy(html);
    }
    cJSON_Delete(ctx);
  }

  static void handle_index(cwist_http_request *req, cwist_http_response *res) {
    (void)req;
    cJSON *ctx = cJSON_CreateObject();
    cJSON_AddStringToObject(ctx, &quot;title&quot;, &quot;CWIST Example&quot;);
    cJSON_AddStringToObject(ctx, &quot;greeting&quot;, &quot;Hello from CWIST&quot;);
    render(res, &quot;templates/index.html&quot;, ctx);
  }

  static void handle_<em>users</em>(cwist_http_request *req, cwist_http_response *res) {
    (void)req;
    if (!g_db_pool) return <em>send</em>_error(res, &quot;database pool unavailable&quot;);

    cwist_db_pool_exec(g_db_pool,
      &quot;CREATE TABLE IF NOT EXISTS <em>users</em> (id INTEGER PRIMARY KEY, name TEXT);&quot;
      &quot;INSERT INTO <em>users</em> (name) SELECT 'Alice' WHERE NOT EXISTS &quot;
      &quot;(SELECT 1 FROM <em>users</em> WHERE name = 'Alice');&quot;
      &quot;INSERT INTO <em>users</em> (name) SELECT 'Bob' WHERE NOT EXISTS &quot;
      &quot;(SELECT 1 FROM <em>users</em> WHERE name = 'Bob');&quot;);

    cJSON *rows = NULL;
    if (cwist_db_pool_query(g_db_pool,
        &quot;SELECT id, name FROM <em>users</em> ORDER BY id;&quot;, &amp;rows).error.err_i16)
      return <em>send</em>_error(res, &quot;failed <em>to</em> query database&quot;);

    cJSON *ctx = cJSON_CreateObject();
    cJSON_AddItemToObject(ctx, &quot;<em>users</em>&quot;, rows ? rows : cJSON_CreateArray());
    render(res, &quot;templates/<em>users</em>.html&quot;, ctx);
  }

  static void handle_health(cwist_http_request *req, cwist_http_response *res) {
    (void)req;
    cwist_http_header_add(&amp;res-&gt;headers, &quot;Content-Type&quot;, &quot;text/plain&quot;);
    cwist_sstring_assign(res-&gt;body, &quot;ok&quot;);
  }

  int main(void) {
    g_db_pool = cwist_db_pool_create(&quot;./app.db&quot;, 1);
    if (!g_db_pool) return 1;

    cwist_app *app = cwist_app_create();
    cwist_app_get(app, &quot;/&quot;, handle_index);
    cwist_app_get(app, &quot;/<em>users</em>&quot;, handle_<em>users</em>);
    cwist_app_get(app, &quot;/health&quot;, handle_health);
    cwist_app_use_https(app, &quot;cert.pem&quot;, &quot;key.pem&quot;);
    cwist_app_listen(app, 8082);
    cwist_app_destroy(app);
    cwist_db_pool_destroy(g_db_pool);
    return 0;
  }

</code></pre>
Code style is old and still small. The code is simple and stupid.<p>CWIST functions use the same `cwist_xx_xx` naming format. It's consistent. It's harder <em>to</em> make a slop in CWIST.<p>Features<p>- CWIST GC for fast prototyping. It's closer <em>to</em> a garbage sweeper than a traditional GC, and lighter.
